class Resource { int id; public: Resource(int i): id(i) {} };
std::allocator<Resource> alloc;
size_t N = 10;

// 1. Allocate raw, uninitialized memory
Resource* raw_storage = alloc.allocate(N);

// 2. Source data
std::vector<Resource> src = { {100}, {200}, {300} };

// 3. Construct objects via uninitialized_copy_n (uses placement new)
Resource* constructed_end = 
    std::uninitialized_copy_n(src.begin(), 3, raw_storage);

// 4. Manual Destruction (Required for allocated objects)
std::destroy(raw_storage, constructed_end);

// 5. Deallocate memory
alloc.deallocate(raw_storage, N);
